-- These quest spells need a spell focus object near their target: Tuber Whistle (36652, focus 1424); Planting Bundle of Bloodthistle (37062, focus 1432).
-- 1 object(s) had no usable template and 21 of their spawns were missing, so the casts failed with a requirement error.
-- Based on Legends of Azeroth 5.4.8.

DELETE FROM `gameobject_template` WHERE `entry` IN (184841);

DELETE FROM `gameobject` WHERE `guid` BETWEEN 911614 AND 911634;
